#[allow(clippy::redundant_closure, clippy::useless_conversion)]
impl From<CommandMessage> for edax_abi::CommandMessage {
    fn from(val: CommandMessage) -> Self {
        Self {
            id: val.id,
            idempotency_key: val.idempotency_key,
            aggregate_id: val.aggregate_id,
            tenant: val.tenant,
            name: val.name,
            version: val.version,
            data: val.data.to_vec().into(),
            correlation_id: val.correlation_id,
            causation_id: val.causation_id,
            issued_at: val.issued_at,
            extensions: val.extensions.into_iter().map(|(k, v)| (k.into(), v.into())).collect(),
            metadata: val.metadata.into_iter().map(|(k, v)| (k.into(), v.into())).collect(),
        }
    }
}

#[allow(clippy::redundant_closure, clippy::useless_conversion)]
impl From<edax_abi::CommandMessage> for CommandMessage {
    fn from(val: edax_abi::CommandMessage) -> Self {
        Self {
            id: val.id.to_string(),
            idempotency_key: val.idempotency_key.map(|v| v.to_string()),
            aggregate_id: val.aggregate_id.map(|v| v.to_string()),
            tenant: val.tenant.map(|v| v.to_string()),
            name: val.name.to_string(),
            version: val.version,
            data: val.data.to_vec().into(),
            correlation_id: val.correlation_id.to_string(),
            causation_id: val.causation_id.to_string(),
            issued_at: val.issued_at,
            extensions: val.extensions.into_iter().map(|(k, v)| (k.into(), v.into())).collect(),
            metadata: val.metadata.into_iter().map(|(k, v)| (k.into(), v.into())).collect(),
        }
    }
}

